import * as THREE from 'three';
import { COLLISION_LAYER } from '../physics/Physics.js';

/**
 * Surface resolution for character placement.
 *
 * `physics.groundHeight` answers "what is the first thing below this point",
 * and `physics.groundHeightOrFallback` answers "what is the *topmost* thing at
 * this column". Neither is the question a spawner actually asks, which is:
 * *which of the several surfaces stacked at this column is a person supposed to
 * be standing on?* A station deck under a 24 m gantry has three surfaces in the
 * column; a keep has four. Picking the top one drops civilians on rooftops,
 * picking the first one below an authored height drops them into basements, and
 * a single ring probe cannot tell either case apart.
 *
 * So this module walks the whole stack, keeps only the surfaces that are
 * genuinely walkable (flat enough, with head clearance up to the next surface
 * above), and returns the one closest to where the author meant. Everything
 * that places or repairs a character goes through here.
 *
 * All of it is spawn-time or watchdog-rate work - never per-frame - so the
 * raycasts and the small result array are affordable.
 */

/**
 * Below this the surface is a wall or a steep roof, not a floor. 56.6 degrees.
 *
 * ── This is NOT the slope a character can actually walk up ────────────────
 * It is the right threshold for the question it is asked here, where the
 * normal comes from a RAYCAST and is the true face normal. But it is also read
 * by `Player._move` and `Navigation._probe` against normals that come out of
 * `Physics.resolveCapsule`, and those stop being the true face normal past
 * ~44 degrees: a moving capsule on a 46 degree ramp reports about 0.44 here,
 * not 0.69, so it reads as a wall to be stepped over rather than as floor.
 *
 * The ceiling in effect for the standing player is therefore ~45 degrees, not
 * the 56.6 this number implies - and past it the player is not stopped, it is
 * laddered up by the step-up probe at up to 7.3 m/s of climb against a 6.0 m/s
 * ground speed cap. `Physics.resolveCapsule` has its own third number, 0.64
 * (50.2 degrees), for `grounded`.
 *
 * Do not raise or lower this expecting the walkable ceiling to move with it;
 * it will not until the solver's closest point is fixed. The mechanism, the
 * measurements and why the fix was not taken alone are at the closest-point
 * iteration in `Physics.resolveCapsule`.
 * @see ../physics/Physics.js `resolveCapsule`
 * @see ../../scripts/tests/capsule-normal.test.mjs
 */
const WALKABLE_NORMAL_Y = 0.55;
/** A person needs this much clear air above a surface to stand on it. */
const STANDING_HEADROOM = 1.85;
/** Nudge the next cast below the surface we just found, to avoid re-hitting it. */
const STACK_EPSILON = 0.02;
/**
 * Hard cap on stacked surfaces per column.
 *
 * This used to be 10, and 10 was not enough - it is the whole of the "NPCs on
 * the station ceiling" defect. The station hub is roofed by a raft of services
 * rather than a plate: measured down the column at (107.7, 10.9), the surfaces
 * are the dome at 168.47 and then 62.00, 61.70, 60.35, 60.25, 60.20, 60.09,
 * 59.65, 59.23, 58.57 - nine ceiling members - and the DECK is the eleventh
 * entry. At (88.9, -71.8) the raft is twelve deep and the deck is thirteenth.
 * A walk capped at 10 therefore never reached the floor, `resolveSurfaceY` was
 * handed a candidate list made entirely of ceiling members, and the character
 * standing on the deck was told the surface it belonged on was 62 m overhead.
 *
 * The cap is still needed - a runaway column would cost unbounded raycasts -
 * but it has to sit above what these worlds actually build. Twenty-four is
 * twice the deepest column measured on the station, which is by a distance the
 * densest ceiling in the game.
 */
const MAX_STACK = 24;
/**
 * How far above the hint the anchored search in `resolveSurfaceY` starts.
 *
 * The cap above is a safety net, not the fix. The real flaw was that the walk
 * starts at the top of the WORLD, so it spends its budget on the surfaces
 * furthest from the height anybody asked about and truncates before it reaches
 * the ones that matter. Anchoring the walk near the hint spends the budget
 * where the answer lives.
 *
 * Twelve metres is three storeys of the station's 3.9 m grid: deep enough to
 * find the floor above a character that has been buried under a deck, and far
 * short of the 58 m between the station deck and the underside of its ceiling
 * raft, which is the gap that has to stay uncrossable.
 *
 * It is also cheaper, which is worth saying because a correctness fix usually
 * is not: the anchored walk stops one or two casts in where the old one drilled
 * through the whole raft first. Timed over 2,000 station deck columns, 34.5 us
 * a call against 160.1.
 */
const SEARCH_ABOVE = 12;

/** surfaceStack() owns these two exclusively. */
const _ssOrigin = new THREE.Vector3();
const _ssDown = new THREE.Vector3(0, -1, 0);

/**
 * Every walkable-or-not surface in the column at (x, z), highest first.
 *
 * @param {any} physics
 * @param {number} x
 * @param {number} z
 * @param {number} [topY] height to start casting from
 * @param {number} [bottomY] stop once we drop past this
 * @returns {Array<{y:number, normalY:number, walkable:boolean, headroom:number}>}
 */
export function surfaceStack(physics, x, z, topY = 400, bottomY = -80) {
  const out = [];
  let y = topY;
  for (let i = 0; i < MAX_STACK; i++) {
    _ssOrigin.set(x, y, z);
    const hit = physics.raycast(_ssOrigin, _ssDown, y - bottomY, COLLISION_LAYER.WORLD);
    if (!hit) break;
    const ny = Math.abs(hit.normal?.y ?? 1);
    const sy = hit.point.y;
    out.push({ y: sy, normalY: ny, walkable: ny >= WALKABLE_NORMAL_Y, headroom: Infinity });
    y = sy - STACK_EPSILON;
    if (y <= bottomY) break;
  }
  // Headroom is the gap up to the underside of whatever is stacked above. Using
  // the stack rather than an upward raycast is deliberate: world geometry is
  // single-sided, so a ray fired up from under a deck passes straight through
  // it and reports infinite clearance.
  for (let i = 0; i < out.length; i++) {
    out[i].headroom = i === 0 ? Infinity : out[i - 1].y - out[i].y;
  }
  return out;
}

/**
 * Pick the surface a character should stand on at (x, z).
 *
 * Preference order: walkable, has standing headroom, and then nearest to
 * `hintY` - the height the author (or the character's own current position)
 * implies. That is what keeps a civilian authored under a gantry on the deck
 * instead of on the gantry, and keeps one authored on a rampart on the rampart.
 *
 * @param {any} physics
 * @param {number} x
 * @param {number} z
 * @param {number} hintY intended height
 * @returns {number|null} surface height, or null if the column has no floor
 */
export function resolveSurfaceY(physics, x, z, hintY) {
  /* Anchored search first. See SEARCH_ABOVE: a walk that starts at the top of
   * the world answers a question nobody asked and can run out of budget before
   * it reaches the floor under the character's feet. */
  const near = pickSurface(surfaceStack(physics, x, z, hintY + SEARCH_ABOVE), hintY);
  if (near !== null) return near;
  /* Nothing standable anywhere near the hint - a character that has fallen out
   * from under the world, or a spawn authored into empty air. The full-column
   * walk always returns something if the column has anything at all in it. */
  return pickSurface(surfaceStack(physics, x, z, Math.max(hintY + 300, 400)), hintY);
}

/**
 * Score a stack and return the height a character should stand at, or null when
 * the stack is empty.
 *
 * Split out of `resolveSurfaceY` so the anchored search and the whole-column
 * fallback score identically - the two differ only in where they look.
 *
 * @param {ReturnType<typeof surfaceStack>} stack
 * @param {number} hintY
 * @returns {number|null}
 */
export function pickSurface(stack, hintY) {
  if (stack.length === 0) return null;
  let best = null;
  let bestScore = Infinity;
  for (const s of stack) {
    if (!s.walkable) continue;
    // A surface with a ceiling closer than a person is tall is a crawlspace, not
    // a floor. It is still better than nothing, so it is scored rather than
    // rejected outright.
    const cramped = s.headroom < STANDING_HEADROOM ? 40 : 0;
    const score = Math.abs(s.y - hintY) + cramped;
    if (score < bestScore) {
      bestScore = score;
      best = s;
    }
  }
  if (best) return best.y;
  // No walkable surface at all: a steep roof still beats falling forever.
  let fallback = stack[0];
  for (const s of stack) if (Math.abs(s.y - hintY) < Math.abs(fallback.y - hintY)) fallback = s;
  return fallback.y;
}

/**
 * Resolve an authored spawn onto a real, standable surface, searching outward
 * if the exact column has no floor at all.
 *
 * @param {any} physics
 * @param {THREE.Vector3} p authored point (`p.y` is the hint)
 * @param {THREE.Vector3} [out]
 * @returns {THREE.Vector3|null} null only when the whole neighbourhood is empty
 */
export function resolveSpot(physics, p, out) {
  if (!p) return null;
  const v = out ?? new THREE.Vector3();
  const direct = resolveSurfaceY(physics, p.x, p.z, p.y);
  if (direct !== null) return v.set(p.x, direct, p.z);
  for (const r of [1.5, 3, 6, 12]) {
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * Math.PI * 2;
      const x = p.x + Math.cos(a) * r;
      const z = p.z + Math.sin(a) * r;
      const y = resolveSurfaceY(physics, x, z, p.y);
      if (y !== null) return v.set(x, y, z);
    }
  }
  return null;
}

/**
 * Is this character standing somewhere a person could actually stand?
 *
 * Used by the spawn validator and by the runtime watchdog. "Underground" is not
 * "there is something above me" - a deck under a gantry is fine - it is "there
 * is no floor at my feet", or "the floor I should be on is well above me".
 *
 * @param {any} physics
 * @param {THREE.Vector3} position feet position
 * @param {number} hintY the height this character is supposed to be near
 * @returns {{ok:boolean, surfaceY:number|null, drop:number}}
 */
export function auditStanding(physics, position, hintY) {
  const y = resolveSurfaceY(physics, position.x, position.z, hintY);
  if (y === null) return { ok: false, surfaceY: null, drop: Infinity };
  const drop = y - position.y;
  // Tolerance is asymmetric on purpose: a few centimetres of float is a stale
  // ground sample and harmless, but being *below* the resolved floor at all
  // means the character is inside geometry.
  return { ok: drop < 0.35 && drop > -1.2, surfaceY: y, drop };
}

/* ------------------------------------------------------------------------ */
/* Standing on a SLOPE                                                       */
/* ------------------------------------------------------------------------ */

/**
 * How far above the vertical ground height a capsule's feet have to sit before
 * the capsule stops intersecting a sloped surface.
 *
 * ── The defect this closes: characters slid down every ramp in the game ──
 * A capsule's lowest point is the bottom of a sphere of radius `r` whose centre
 * is `r` above the feet. Resting on FLAT ground that sphere is exactly tangent,
 * which is why placing the feet at `groundHeight` has always worked. On a plane
 * pitched at `p` the perpendicular distance from that same centre to the plane
 * is `r * cos(p)`, not `r` - so feet placed at the vertical ground height leave
 * the sphere `r * (1 - cos p)` INSIDE the slab, and `resolveCapsule` evicts it
 * along the surface normal, which on a slope has a horizontal component
 * pointing downhill.
 *
 * That eviction is not a transient. `NPC._followGround` puts the feet back on
 * the ground height every step, so the character is re-buried every step and
 * pushed downhill again: measured against the station's walkway flight
 * (30.5 degrees, capsule radius 0.33), a steady 0.0231 m of downhill drift per
 * fixed step, which is 1.39 m/s against a 1.4 m/s walk. A character aimed
 * straight up that flight climbed 1.7 m in fourteen seconds and then fell off
 * the side of it. Every ramp, stair flight and escalator in every world was on
 * the same treadmill; the steeper the flight, the faster it ran.
 *
 * Lifting the feet by `r * (1/cos p - 1)` puts the sphere exactly tangent to
 * the slope, so there is nothing for the solver to evict. `normalY` IS `cos p`,
 * which is why the ground normal is what this takes rather than an angle. Flat
 * ground gives `normalY === 1` and a lift of exactly zero, so nothing that was
 * standing on a floor moves by so much as a float.
 *
 * ── For characters that RE-SEAT their feet. The player must NOT be given it ──
 * The defect is not a property of the capsule or of the solver; it is a property
 * of writing the feet back to the vertical ground height every step. `Player`
 * never does that - it leaves the capsule wherever `resolveCapsule` left it, and
 * a capsule the solver has finished evicting from a slope is already tangent to
 * it. Driven up ramps from 10 to 45 degrees with no lift applied at all, the
 * player's feet settle at exactly this height less a small term for its
 * ground-stick bias, and it shows no downhill drift climbing any of them.
 * Adding a lift there would hold the player off the ground.
 * @see ../player/Player.js `_move`
 * @see ../../scripts/tests/player-slope.test.mjs
 *
 * @param {number} radius capsule radius
 * @param {number} normalY Y component of the surface normal (= cos of pitch)
 * @returns {number} metres to add to the ground height
 */
export function capsuleSlopeLift(radius, normalY) {
  if (!(radius > 0) || !Number.isFinite(normalY)) return 0;
  // Anything below the walkable threshold is a wall being brushed rather than a
  // floor being stood on; clamping there stops a grazing contact with a facade
  // asking for an absurd lift.
  const ny = Math.min(1, Math.max(WALKABLE_NORMAL_Y, normalY));
  return radius * (1 / ny - 1);
}

/* ------------------------------------------------------------------------ */
/* Reachability - "could this character have walked to that height?"          */
/* ------------------------------------------------------------------------ */

/**
 * Fastest a moving surface in these worlds carries a standing rider, m/s.
 *
 * The station lift runs at 2.6 (`InteriorKit`), the escalators at 1.15 along a
 * 30-degree flight which is 0.58 vertical, and the travelators are flat. Three
 * is the lift with room to spare, and nothing else in any world moves a
 * standing character upward at all.
 */
export const CARRY_SPEED = 3;

/**
 * How far above a character one simulated step of walking can put it.
 *
 * `stepReach` is the caller's own ground-probe reach - the height of the tallest
 * thing its ground follower can pull it up onto in a single step, which for a
 * character is `GROUND_PROBE_UP`. The `dt` term is the moving-surface case: a
 * rider carried by a lift gains height without any step at all, and a character
 * simulated in a demoted LOD band is handed up to `SIM_MAX_STEP` seconds of it
 * in one go.
 *
 * @param {number} dt seconds of simulation about to be integrated
 * @param {number} stepReach the ground follower's own reach, metres
 * @returns {number} metres
 */
export function reachableRise(dt, stepReach) {
  return stepReach + CARRY_SPEED * Math.max(0, dt);
}

/**
 * The height a character has *walked* to, updated for one simulated step.
 *
 * This is the memory the whole anti-climbing rule is built on, and it is
 * deliberately asymmetric:
 *
 *   - downward moves freely. Anyone can fall, and a character that drops 20 m
 *     off a walkway has genuinely arrived at the bottom.
 *   - upward follows only as far as one step of walking could carry it. A stair
 *     riser, an escalator tread, a ramp and a lift car all clear that bound
 *     comfortably every step, so a character using any of them is tracked the
 *     whole way up.
 *   - an upward jump larger than that is not walking, so the memory does NOT
 *     follow it. That is the point: a character teleported onto the ceiling
 *     keeps remembering the deck, which is what lets the watchdog recognise it
 *     as stranded and put it back. If this followed, the character would simply
 *     have redefined "where I belong" and stayed there forever.
 *
 * @param {number} lastWalkedY the height remembered so far
 * @param {number} y where the character is now
 * @param {number} reach @see reachableRise
 * @returns {number} the height to remember
 */
export function walkedHeight(lastWalkedY, y, reach) {
  if (y <= lastWalkedY) return y;
  return y - lastWalkedY <= reach ? y : lastWalkedY;
}

/**
 * How far above the height it walked to a character may be found before it is
 * treated as stranded rather than as standing somewhere.
 *
 * `walkedHeight` already tracks every legitimate climb step by step, so a
 * character using a staircase, a ramp, an escalator or a lift never builds any
 * excess at all - the honest threshold is therefore near zero and this is pure
 * headroom. It has to clear the largest single step the tracker itself allows,
 * which is `reachableRise` at the longest step the simulation ever hands out
 * (`SIM_MAX_STEP` = 0.4 s -> 0.95 + 3 x 0.4 = 2.15 m), so 3 m is that with a
 * margin and still twenty times smaller than the smallest escape observed.
 */
export const STRAND_LIMIT = 3;

/**
 * Is this character somewhere it could not have walked to?
 *
 * @param {number} lastWalkedY @see walkedHeight
 * @param {number} y where the character is now
 * @param {number} [limit]
 * @returns {boolean}
 */
export function isStranded(lastWalkedY, y, limit = STRAND_LIMIT) {
  return y - lastWalkedY > limit;
}

/**
 * Clamp a re-seat so it can only put a character where it could have walked.
 *
 * Applied to every runtime correction that moves a character. Lifting one out of
 * the floor it has sunk into is a correction; lifting one onto a surface it
 * could never have reached on foot is a relocation, and a relocation is what
 * every reported "NPC on the ceiling" actually was.
 *
 * Called only once the caller has decided a correction is wanted.
 *
 * @param {number} lastWalkedY @see walkedHeight
 * @param {number} y where the character is now
 * @param {number|null} surfaceY where the surface resolver wants to put it
 * @param {number} [limit]
 * @returns {number|null} the height to move to, or null to leave it alone
 */
export function reseatY(lastWalkedY, y, surfaceY, limit = STRAND_LIMIT) {
  const ceiling = lastWalkedY + limit;
  /* The resolver wants a height this character could not have reached on foot.
   * Refuse it - and if the character is ALREADY up there, the last height it
   * really did walk to is the only trustworthy answer left. */
  if (surfaceY === null || surfaceY > ceiling) {
    return isStranded(lastWalkedY, y, limit) ? lastWalkedY : null;
  }
  return surfaceY;
}

/**
 * How deep a character will wade before water counts as impassable.
 *
 * Knee-deep is a puddle you walk through; waist-deep is a river you go around.
 * Characters have no swimming animation and no buoyancy - only the player does -
 * so anything past this is somewhere they simply must not be.
 */
export const WADE_DEPTH = 0.75;

/**
 * Depth of standing water over the column at (x, z), in metres. 0 when dry.
 *
 * `WaterVolumes` knows where the *surface* is; the bed is collision geometry,
 * which it deliberately does not own - so the depth is the gap between the two.
 * That matters: the medieval river is 1.5 m in the channel and a few
 * centimetres at the margins, and a character should be free to walk the
 * margins.
 *
 * Cost is one grid lookup, and a raycast *only* where there is water overhead -
 * so away from the river this is a hash miss and nothing else, which is what
 * makes it affordable to call from steering every frame.
 *
 * ── WHY THERE IS A PROBE HEIGHT ───────────────────────────────────────────
 * The bed ray used to start, always, at `surfaceY + 1.0`. Over the medieval
 * river that is y = 1.85, and EVERY DECK IN THE VALE IS ABOVE IT: the Aldern
 * bridge carries its road at 4.35 m, Harrowgate at 3.30, the Ashlea planks at
 * 2.92 and the Greyoak stage at 2.60. A ray that starts under a bridge cannot
 * see the bridge, so it returned the riverbed and a character standing on dry
 * planks measured 1.4-2.6 m of river against a 0.75 m wading depth. Everything
 * downstream then believed it: steering refused to path onto a deck, the
 * grounding watchdog teleported anyone who reached one into the nearest bank,
 * and a predator whose target stood on a bridge could neither charge it nor
 * circle it.
 *
 * So the caller may say how high the thing asking about this column is
 * standing, and the ray starts a metre above the HIGHER of that and the water.
 * Two properties, and both are why this is a probe height rather than a flag:
 *
 *   - it can only ever turn deep water into dry, never the reverse, and only
 *     where there is real collision geometry above the waterline at that
 *     column - a deck, a jetty, an abutment. Over open river the ray falls
 *     past the surface to the bed exactly as it always did;
 *   - and something standing IN the river reports its own feet, which are at
 *     or below the surface, so `Math.max` picks the water and the answer is
 *     unchanged. That is what stops this reintroducing the wolf that stood
 *     1.7 m out of its depth at (-28.87, 113.44).
 *
 * Omitting it is the old behaviour exactly, so every caller that has no height
 * to offer - a wander destination, a spawn repair - keeps the conservative
 * answer it always got.
 *
 * @param {any} physics
 * @param {{surfaceYAt:(x:number,z:number)=>number|null}|null} water
 * @param {number} x
 * @param {number} z
 * @param {number} [probeY] world height of whatever is asking about this column
 * @returns {number} depth in metres, 0 if dry, Infinity if the bed is missing
 */
export function waterDepthAt(physics, water, x, z, probeY = -Infinity) {
  if (!water) return 0;
  const surfaceY = water.surfaceYAt(x, z);
  if (surfaceY === null) return 0;
  const lift = probeY > surfaceY ? probeY - surfaceY : 0;
  // The drop grows with the lift, so the ray always reaches as far BELOW the
  // waterline as it did before - starting higher must not shorten its reach.
  const bedY = physics.groundHeight(x, z, surfaceY + lift + 1.0, 40 + lift);
  // Water over a hole in the collision mesh: no bed to stand on at all, so this
  // is as impassable as it gets.
  if (bedY === null) return Infinity;
  const d = surfaceY - bedY;
  return d > 0 ? d : 0;
}

/**
 * Is this column too deep to stand in?
 * @param {number} [probeY] @see waterDepthAt
 * @returns {boolean}
 */
export function isDeepWater(physics, water, x, z, probeY) {
  return waterDepthAt(physics, water, x, z, probeY) > WADE_DEPTH;
}

/**
 * Nearest dry-enough spot to `p`, searching outward in rings.
 *
 * Used to keep spawns and repairs out of the river. Returns the original point
 * when it is already dry, and null when the whole neighbourhood is water - the
 * caller decides whether that is fatal.
 *
 * @param {any} physics
 * @param {any} water
 * @param {THREE.Vector3} p
 * @param {THREE.Vector3} [out]
 * @returns {THREE.Vector3|null}
 */
export function nearestDrySpot(physics, water, p, out) {
  const v = out ?? new THREE.Vector3();
  if (!water || !isDeepWater(physics, water, p.x, p.z)) return v.copy(p);
  for (const r of [2, 4, 7, 11, 16, 22, 30]) {
    for (let i = 0; i < 10; i++) {
      const a = (i / 10) * Math.PI * 2;
      const x = p.x + Math.cos(a) * r;
      const z = p.z + Math.sin(a) * r;
      if (isDeepWater(physics, water, x, z)) continue;
      const y = resolveSurfaceY(physics, x, z, p.y);
      if (y === null) continue;
      return v.set(x, y, z);
    }
  }
  return null;
}

/** seatSurfaceAt() owns these exclusively. */
const _seatRing = new THREE.Vector3();

/**
 * Look for something bench-height to sit on at (x, z).
 *
 * A seat reads as a *narrow* raised surface: 0.34-0.68 m above the floor around
 * it, with that floor still present a short step away in most directions. That
 * signature catches benches, planter rims, low walls and bleacher treads, and
 * rejects tables, crates the size of a room, and the tops of buildings - all
 * without any authored seat data, which none of these worlds have.
 *
 * @param {any} physics
 * @param {number} x
 * @param {number} z
 * @param {number} floorY height of the surrounding floor
 * @returns {number|null} seat height
 */
export function seatSurfaceAt(physics, x, z, floorY) {
  const stack = surfaceStack(physics, x, z, floorY + 12);
  let seat = null;
  for (const s of stack) {
    const h = s.y - floorY;
    if (h >= 0.34 && h <= 0.68 && s.walkable && s.headroom > 1.0) {
      seat = s.y;
      break;
    }
  }
  if (seat === null) return null;
  // Confirm the floor comes back around it, so we are sitting on a bench rather
  // than on the edge of a mezzanine.
  let openSides = 0;
  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * Math.PI * 2;
    _seatRing.set(x + Math.cos(a) * 0.95, floorY + 0.9, z + Math.sin(a) * 0.95);
    const y = resolveSurfaceY(physics, _seatRing.x, _seatRing.z, floorY);
    if (y !== null && Math.abs(y - floorY) < 0.3) openSides++;
  }
  return openSides >= 2 ? seat : null;
}

export { WALKABLE_NORMAL_Y, STANDING_HEADROOM };
